// The visitor's drawing is kept in image coordinates, independent of screen size.
export function paintKeepsake(canvas,image,strokes){
 const box=canvas.getBoundingClientRect(),w=box.width||canvas.width,h=box.height||canvas.height,dpr=box.width?Math.min(devicePixelRatio||1,2):1;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.fillStyle='#f5f7ee';ctx.fillRect(0,0,w,h);const scale=Math.min(w/1536,h/1024),ox=(w-1536*scale)/2,oy=(h-1024*scale)/2;ctx.save();ctx.translate(ox,oy);ctx.scale(scale,scale);ctx.globalAlpha=.5;ctx.drawImage(image,0,0,1536,1024);ctx.globalAlpha=1;ctx.strokeStyle='#164f9b';ctx.fillStyle='#164f9b';ctx.lineWidth=18;ctx.lineCap='round';ctx.lineJoin='round';for(const line of strokes){if(!line.length)continue;ctx.beginPath();line.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));if(line.length===1){ctx.arc(line[0][0],line[0][1],9,0,Math.PI*2);ctx.fill();}else ctx.stroke();}ctx.restore();
}
export function sketchPoint(event,canvas){const b=canvas.getBoundingClientRect(),s=Math.min(b.width/1536,b.height/1024);return[(event.clientX-b.left-(b.width-1536*s)/2)/s,(event.clientY-b.top-(b.height-1024*s)/2)/s].map((n,i)=>Math.max(0,Math.min(i?1024:1536,n)));}
export function suggestedRim(image){const c=document.createElement('canvas');c.width=image.naturalWidth;c.height=image.naturalHeight;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);const pixels=ctx.getImageData(0,0,c.width,c.height).data,line=[];for(let x=c.width*.24;x<c.width*.76;x+=8){x=Math.round(x);let y=c.height-1;while(y>c.height*.6&&pixels[(y*c.width+x)*4+3]<190)y--;if(y>c.height*.6)line.push([x,y+8]);}return line;}
